182: 		resolve: (v: { readonly bytesWritten: number }) => void;
183: 		reject: (reason: unknown) => void;
184: 		settled: boolean;
185: 	}[] = [];
186: 	const transports: { call: number; bytes: number }[] = [];
187: 	try {
188: 		const resource = new SpendingResource(
189: 			origin,
190: 			checked,
191: 			mode,
192: 			(payload) => {
193: 				if (calls.length >= 64 || Buffer.byteLength(payload) > 4096)
194: 					throw new TypeError("proof transport capacity");
195: 				return new Promise((resolve, reject) => {
196: 					calls.push({ payload, resolve, reject, settled: false });
197: 				});
198: 			},
199: 			() => handle.close(),
200: 		);
201: 		return Object.freeze({
202: 			resource,
203: 			get attemptedPayloads(): readonly string[] {
204: 				return Object.freeze(calls.map((c) => c.payload));
205: 			},
206: 			get transportAttempts(): readonly Readonly<{ call: number; bytes: number }>[] {
207: 				return Object.freeze(transports.map((t) => Object.freeze({ ...t })));
208: 			},
209: 			async settle(callIndex: number, result: ProofSettlement) {
210: 				if (
211: 					!Number.isSafeInteger(callIndex) ||
212: 					callIndex < 0 ||
213: 					!["full", "short1", "reject-before-write", "pending"].includes(result)
214: 				)
215: 					throw new TypeError("invalid proof settlement");
216: 				const call = calls[callIndex];
217: 				if (!call || call.settled) throw new TypeError("proof call missing or already settled");
218: 				call.settled = true;
219: 				if (result === "pending") return;
220: 				if (result === "reject-before-write") {
221: 					call.reject(new Error("proof reject before write"));
222: 					return;
223: 				}
224: 				const full = Buffer.from(call.payload);
225: 				const bytes = result === "short1" ? full.subarray(0, 1) : full;
226: 				transports.push({ call: callIndex, bytes: bytes.length });
