228: 					call.resolve(await handle.writeBytes(bytes));
229: 				} catch (error) {
230: 					call.reject(error);
231: 				}
232: 			},
233: 		});
234: 	} catch (error) {
235: 		await handle.close();
236: 		throw error;
237: 	}
