12: 	readonly name?: string;
13: 	readonly diagnostics?: "off" | "summary";
14: }
15: export interface SpendingCreationInputs extends Omit<SpendingInputs, "inbox"> {
16: 	readonly inbox: Readonly<{ resource: SpendingResource }>;
17: }
