180: 	const calls: {
181: 		payload: string;
182: 		resolve: (v: { readonly bytesWritten: number }) => void;
183: 		reject: (reason: unknown) => void;
184: 		settled: boolean;
185: 	}[] = [];
186: 	const transports: { call: number; bytes: number }[] = [];
187: 	try {
