570: 	/** B1: share discovery order; only materialization is local. Mount reads stay unchanged. */
571: 	private _describe(_prefix: string, incoming?: ReadonlySet<Node<unknown>>): DescribeSnapshot {
572: 		// D51: edges derive from each node's CURRENT/LIVE deps (entry.node.deps, NOT the
573: 		// construction-time entry.deps), so a rewire (C-8 immediate / C-11 *Map deferred) is
574: 		// reflected and every edge is a real current subscription (D3). A live dep absent from this
575: 		// graph's index (a runtime *Map inner / bare fromAny node) is AUTO-DISCOVERED as a snapshot
576: 		// node with a synthesized stable id (B2). B38 extends this to transitive live-reachability:
577: 		// discovered unregistered nodes are recursively expanded through their own live deps.
578: 		const discovered = new Map<Node<unknown>, string>(); // unregistered live dep → synth local id
579: 		const localId = (n: Node<unknown>): string => {
580: 			const e = this._entries.get(n);
581: 			if (e) return `${_prefix}${e.id}`;
582: 			// unregistered: a stable synthetic id, cached so successive describes + both call sites
583: 			// agree; the `~` prefix can't collide with a registered name or `factory#seq`.
584: 			let sid = this._synthIds.get(n);
585: 			if (sid === undefined) {
586: 				// the `~` prefix avoids the registered `name`/`factory#seq` space; guard the
587: 				// pathological case of a user node literally named `~factory#n` (bump until free).
588: 				do {
589: 					sid = `~${n.factory ?? "?"}#${this._synthSeq++}`;
590: 				} while (this._byId.has(sid));
591: 				this._synthIds.set(n, sid);
592: 			}
593: 			discovered.set(n, sid);
594: 			return `${_prefix}${sid}`;
595: 		};
596: 		const nodes: DescribeNode[] = [];
597: 		const edges: DescribeEdge[] = [];
598: 		// pass 1: registered nodes, reading LIVE deps (localId records any unregistered inner).
599: 		for (const entry of this._entries.values()) {
600: 			const id = `${_prefix}${entry.id}`;
601: 			const liveIds = entry.node.deps.map(localId);
602: 			if (incoming === undefined) {
603: 				const dnode: DescribeNode = {
604: 					id,
605: 					factory: entry.factory,
606: 					status: entry.node.status,
607: 					deps: liveIds,
608: 				};
609: 				if (entry.name !== undefined) dnode.name = entry.name;
610: 				if (entry.node.cache !== undefined) dnode.value = entry.node.cache; // absent = SENTINEL
611: 				if (entry.node.version !== undefined) dnode.version = entry.node.version;
612: 				if (entry.meta !== undefined) dnode.meta = entry.meta;
613: 				nodes.push(dnode);
614: 			}
615: 			if (incoming === undefined || incoming.has(entry.node)) {
616: 				for (const from of liveIds) edges.push({ from, to: id });
617: 			}
618: 		}
619: 		// pass 2: recursively emit auto-discovered unregistered nodes (D51+B38). localId() may add
620: 		// further unregistered deps to `discovered` while this loop runs; a visited set keeps each
621: 		// discovered node emitted once (stable ids via _synthIds).
622: 		const visited = new Set<Node<unknown>>();
623: 		const queue: Node<unknown>[] = [...discovered.keys()];
624: 		for (let i = 0; i < queue.length; i += 1) {
625: 			const inner = queue[i];
626: 			if (visited.has(inner)) continue;
627: 			visited.add(inner);
628: 			const sid = discovered.get(inner);
629: 			if (sid === undefined) continue;
630: 			const liveIds = inner.deps.map(localId);
631: 			for (const dep of inner.deps) {
632: 				if (!this._entries.has(dep) && !visited.has(dep)) queue.push(dep);
633: 			}
634: 			if (incoming === undefined) {
635: 				const dnode: DescribeNode = {
636: 					id: `${_prefix}${sid}`,
637: 					factory: inner.factory ?? "?",
638: 					status: inner.status,
639: 					deps: liveIds,
640: 				};

