19: function ownValues(raw: unknown, allowed: readonly string[]): Record<string, unknown> {
20: 	if (
21: 		raw === null ||
22: 		typeof raw !== "object" ||
23: 		(Object.getPrototypeOf(raw) !== Object.prototype && Object.getPrototypeOf(raw) !== null)
24: 	)
25: 		throw new TypeError("spending entry requires a plain data object");
26: 	const values: Record<string, unknown> = Object.create(null);
27: 	for (const key of Reflect.ownKeys(raw)) {
28: 		if (typeof key !== "string" || !allowed.includes(key))
29: 			throw new TypeError("unknown spending entry field");
30: 		const descriptor = Object.getOwnPropertyDescriptor(raw, key)!;
31: 		if (!("value" in descriptor)) throw new TypeError("spending entry accessor field");
32: 		values[key] = descriptor.value;
33: 	}
34: 	return values;
35: }
36: function configuration(raw: unknown, inherited?: Readonly<Required<SpendingDefaults>>) {
37: 	const values = ownValues(raw, ["name", "diagnostics"]);
38: 	const name = values.name === undefined ? inherited?.name : values.name;
39: 	const diagnostics =
40: 		values.diagnostics === undefined ? (inherited?.diagnostics ?? "off") : values.diagnostics;
41: 	if (typeof name !== "string" || name.length === 0 || name.length > 256)
42: 		throw new TypeError("spending entry requires a bounded instance name");
43: 	if (diagnostics !== "off" && diagnostics !== "summary")
44: 		throw new TypeError("spending entry diagnostics");
45: 	return Object.freeze({ name, diagnostics });
46: }
