573: 		// construction-time entry.deps), so a rewire (C-8 immediate / C-11 *Map deferred) is
574: 		// reflected and every edge is a real current subscription (D3). A live dep absent from this
575: 		// graph's index (a runtime *Map inner / bare fromAny node) is AUTO-DISCOVERED as a snapshot
576: 		// node with a synthesized stable id (B2). B38 extends this to transitive live-reachability:
577: 		// discovered unregistered nodes are recursively expanded through their own live deps.
578: 		const discovered = new Map<Node<unknown>, string>(); // unregistered live dep → synth local id
579: 		const localId = (n: Node<unknown>): string => {
580: 			const e = this._entries.get(n);
